"""Import the 100 curated Commons photographs and preserve attribution.
Run manually, or via the one-time GitHub Actions importer. Existing photos and
queries are never modified; all downloads finish before destination files change.
"""
import base64
import concurrent.futures
import hashlib
import io
import json
from pathlib import Path
import re
import tempfile
import time
import urllib.parse
import urllib.request
import zlib
from PIL import Image, ImageOps

PAYLOAD = ""
ROOT = Path(__file__).resolve().parents[1]
RECORDS = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))


def download(record):
    target = record["path"]
    if not re.fullmatch(r"data/gallery/plant\d{3}/commons_extra_\d{2}\.jpg", target):
        raise ValueError("Unexpected destination: " + target)
    url = record["url"]
    if urllib.parse.urlparse(url).hostname not in {
        "upload.wikimedia.org", "thumb.wikimedia.org", "commons.wikimedia.org"
    }:
        raise ValueError("Unexpected source host")
    for attempt in range(6):
        try:
            request = urllib.request.Request(url, headers={
                "User-Agent": "PlantSearchCourseGallery/1.0 (https://github.com/FisherYu-yz/PlantSearch)"
            })
            with urllib.request.urlopen(request, timeout=60) as response:
                raw = response.read()
            with Image.open(io.BytesIO(raw)) as original:
                image = ImageOps.exif_transpose(original).convert("RGB")
                image.thumbnail((1200, 1200))
                result = io.BytesIO()
                image.save(result, format="JPEG", quality=90)
            record = dict(record)
            record["sha256"] = hashlib.sha256(result.getvalue()).hexdigest()
            return record, result.getvalue()
        except Exception:
            if attempt == 5:
                raise
            time.sleep(min(2 ** attempt, 16))


def main():
    if len(RECORDS) != 100:
        raise ValueError("Expected exactly 100 curated source records")
    with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
        results = list(pool.map(download, RECORDS))
    # Verify before touching any tracked images.
    if len({record["sha256"] for record, raw in results}) != 100:
        raise ValueError("Unexpected duplicate downloaded image")
    for record, raw in results:
        path = ROOT / record["path"]
        if path.exists() and path.read_bytes() != raw:
            raise FileExistsError("Refusing to replace different existing image: " + str(path))
    for record, raw in results:
        path = ROOT / record["path"]
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(raw)
        print("Imported", record["path"], flush=True)
    records = [record for record, raw in results]
    (ROOT / "data/commons_image_sources.json").write_text(
        json.dumps(records, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )
    plants = json.loads((ROOT / "data/plants.json").read_text(encoding="utf-8-sig"))
    lines = ["# 新增图库图片来源与许可", "",
        "新增100张Wikimedia Commons图片，每类5张。图片经公开分类标签和缩略图筛选，不代表四川大学校园实拍。", "",
        "处理：纠正EXIF方向、转换RGB JPEG，最长边不超过1200像素，JPEG质量90。原有照片的来源需另行整理。", "",
        "| 文件 | 植物 | 作者 | 许可 | 原页面 |", "|---|---|---|---|---|"]
    for record in records:
        clean = lambda value: str(value).replace("|", "/").replace("\n", " ")
        license_url = record["license_url"] or record["page_url"]
        lines.append(f"| {record['path']} | {plants[record['plant_id']]['name']} | {clean(record['author'])} | [{record['license']}]({license_url}) | [{clean(record['title'])}]({record['page_url']}) |")
    (ROOT / "IMAGE_SOURCES.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    print("Completed: 100 added photographs; queries untouched.", flush=True)


if __name__ == "__main__":
    main()
